def seed():
    response = (
        supabase
        .table("atm_locations")
        .insert(ATM_DATA)
        .execute()
    )

    print(f"Inserted {len(response.data)} ATM locations.")

    for atm in response.data:
        print(
            f"{atm['atm_id']} | "
            f"{atm['district']} | "
            f"{atm['lat']}, {atm['lng']}"
        )


if __name__ == "__main__":
    seed()